  while (i < a.length && j < b.length) {
    if (a[i][0] < b[j][0]) out.push([a[i][0], a[i++][1]]);
    else if (a[i][0] > b[j][0]) out.push([b[j][0], b[j++][1]]);
    else out.push([a[i][0], a[i++][1] + b[j++][1]]);
  }
  while (i < a.length) out.push([a[i][0], a[i++][1]]);
  while (j < b.length) out.push([b[j][0], b[j++][1]]);
